import{_ as t,c as i,o as a,ag as o}from"./chunks/framework.CQuhCYrb.js";const g=JSON.parse('{"title":"Discourse Guidelines","description":"","frontmatter":{"title":"Discourse Guidelines"},"headers":[],"relativePath":"community/discourse.md","filePath":"community/discourse.md","lastUpdated":null}'),r={name:"community/discourse.md"};function n(s,e,l,d,h,u){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="discourse-guidelines" tabindex="-1">Discourse Guidelines <a class="header-anchor" href="#discourse-guidelines" aria-label="Permalink to &quot;Discourse Guidelines&quot;">​</a></h1><h2 id="community-standards-for-productive-discussion" tabindex="-1">Community Standards for Productive Discussion <a class="header-anchor" href="#community-standards-for-productive-discussion" aria-label="Permalink to &quot;Community Standards for Productive Discussion&quot;">​</a></h2><p>This page outlines expectations and tools for engaging in productive discourse within the IrregularChat community.</p><h2 id="chatham-house-rules" tabindex="-1">Chatham House Rules <a class="header-anchor" href="#chatham-house-rules" aria-label="Permalink to &quot;Chatham House Rules&quot;">​</a></h2><p>All discussions in this community operate under <strong>Chatham House Rules</strong>:</p><ul><li>Participants are free to use information received during discussions</li><li>The identity or affiliation of the speaker(s), or any other participant, may NOT be revealed</li><li><strong>Screenshots shared outside of the community without permission are not acceptable behavior</strong></li></ul><p>This creates a safe space for open, honest discussion without fear of attribution or retaliation.</p><h2 id="before-engaging-three-questions" tabindex="-1">Before Engaging: Three Questions <a class="header-anchor" href="#before-engaging-three-questions" aria-label="Permalink to &quot;Before Engaging: Three Questions&quot;">​</a></h2><p>Before diving into a discussion, consider these questions:</p><h3 id="_1-is-this-person-engaging-in-good-faith" tabindex="-1">1. Is This Person Engaging in Good Faith? <a class="header-anchor" href="#_1-is-this-person-engaging-in-good-faith" aria-label="Permalink to &quot;1. Is This Person Engaging in Good Faith?&quot;">​</a></h3><p>Look for signs of genuine engagement:</p><ul><li>Are they willing to consider alternative viewpoints?</li><li>Do they respond to your actual points or deflect?</li><li>Are they seeking understanding or just &quot;winning&quot;?</li></ul><h3 id="_2-what-is-the-broader-topic" tabindex="-1">2. What Is the Broader Topic? <a class="header-anchor" href="#_2-what-is-the-broader-topic" aria-label="Permalink to &quot;2. What Is the Broader Topic?&quot;">​</a></h3><ul><li>Is this a specific claim or part of a larger discussion?</li><li>What context might be missing?</li><li>Are there underlying assumptions that need to be addressed first?</li></ul><h3 id="_3-what-is-the-primary-source" tabindex="-1">3. What Is the Primary Source? <a class="header-anchor" href="#_3-what-is-the-primary-source" aria-label="Permalink to &quot;3. What Is the Primary Source?&quot;">​</a></h3><ul><li>Where did this information originate?</li><li>Is the source credible and verifiable?</li><li>Has the information been filtered through secondary sources that may have altered it?</li></ul><hr><h2 id="mental-fallacies-to-watch-for" tabindex="-1">Mental Fallacies to Watch For <a class="header-anchor" href="#mental-fallacies-to-watch-for" aria-label="Permalink to &quot;Mental Fallacies to Watch For&quot;">​</a></h2><p>Are we discussing a mental fallacy? Here are common ones to identify:</p><table tabindex="0"><thead><tr><th>Fallacy</th><th>Description</th></tr></thead><tbody><tr><td><strong>Strawman Argument</strong></td><td>Misrepresenting an opponent&#39;s position to make it easier to attack</td></tr><tr><td><strong>Ad Hominem</strong></td><td>Attacking the person making the argument instead of the argument itself</td></tr><tr><td><strong>Whataboutism (Tu Quoque)</strong></td><td>Deflecting criticism by accusing the opponent of similar or worse behavior</td></tr><tr><td><strong>False Dilemma</strong></td><td>Presenting only two extreme choices when more options exist</td></tr><tr><td><strong>Appeal to Emotion</strong></td><td>Using fear, pity, or outrage instead of logic to persuade</td></tr><tr><td><strong>Slippery Slope</strong></td><td>Claiming one action will inevitably lead to extreme consequences without evidence</td></tr><tr><td><strong>Red Herring</strong></td><td>Distracting from the main issue by introducing an unrelated topic</td></tr><tr><td><strong>Appeal to Authority</strong></td><td>Using a questionable or unrelated authority to support an argument</td></tr><tr><td><strong>Cherry-Picking</strong></td><td>Selecting only favorable evidence while ignoring contradictory data</td></tr><tr><td><strong>Bandwagon Fallacy</strong></td><td>Arguing something is true or right because many people believe it</td></tr></tbody></table><hr><h2 id="bad-faith-tactics-to-recognize" tabindex="-1">Bad Faith Tactics to Recognize <a class="header-anchor" href="#bad-faith-tactics-to-recognize" aria-label="Permalink to &quot;Bad Faith Tactics to Recognize&quot;">​</a></h2><p>Be aware of these manipulation tactics:</p><table tabindex="0"><thead><tr><th>Term</th><th>Definition</th></tr></thead><tbody><tr><td><strong>Grifter</strong></td><td>An individual who leverages political or ideological movements for personal profit</td></tr><tr><td><strong>Bad Faith Argument</strong></td><td>An argument made without intent to engage honestly, often to provoke or derail</td></tr><tr><td><strong>False Flag</strong></td><td>An operation made to appear as if conducted by an opposing group</td></tr><tr><td><strong>Disinfo Agent</strong></td><td>A person believed to intentionally spread false or misleading information</td></tr><tr><td><strong>Astroturfing</strong></td><td>Creating the appearance of grassroots support through coordinated efforts</td></tr><tr><td><strong>Gaslighting</strong></td><td>Causing someone to doubt their memory, perception, or judgment</td></tr><tr><td><strong>Projection</strong></td><td>Attributing one&#39;s own behavior or motives to others</td></tr></tbody></table><hr><h2 id="principles-for-better-discourse" tabindex="-1">Principles for Better Discourse <a class="header-anchor" href="#principles-for-better-discourse" aria-label="Permalink to &quot;Principles for Better Discourse&quot;">​</a></h2><p>Use these mental tools to improve discussions:</p><h3 id="occam-s-razor" tabindex="-1">Occam&#39;s Razor <a class="header-anchor" href="#occam-s-razor" aria-label="Permalink to &quot;Occam&#39;s Razor&quot;">​</a></h3><p>The simplest explanation with the fewest assumptions is usually the correct one.</p><h3 id="hanlon-s-razor" tabindex="-1">Hanlon&#39;s Razor <a class="header-anchor" href="#hanlon-s-razor" aria-label="Permalink to &quot;Hanlon&#39;s Razor&quot;">​</a></h3><p>Never attribute to malice what can be adequately explained by stupidity or ignorance.</p><h3 id="hume-s-guillotine-is-ought-problem" tabindex="-1">Hume&#39;s Guillotine (Is-Ought Problem) <a class="header-anchor" href="#hume-s-guillotine-is-ought-problem" aria-label="Permalink to &quot;Hume&#39;s Guillotine (Is-Ought Problem)&quot;">​</a></h3><p>Just because something <em>is</em> a certain way doesn&#39;t mean it <em>ought</em> to be that way. Descriptive statements don&#39;t automatically imply prescriptive conclusions.</p><h3 id="steelman-principle" tabindex="-1">Steelman Principle <a class="header-anchor" href="#steelman-principle" aria-label="Permalink to &quot;Steelman Principle&quot;">​</a></h3><p>Strengthen your opponent&#39;s argument to its best possible form before engaging with it, rather than attacking a weak version. This is the opposite of a strawman.</p><h3 id="rapoport-s-rules" tabindex="-1">Rapoport&#39;s Rules <a class="header-anchor" href="#rapoport-s-rules" aria-label="Permalink to &quot;Rapoport&#39;s Rules&quot;">​</a></h3><p>Before criticizing someone&#39;s argument:</p><ol><li>Restate their position so clearly that they say &quot;Thanks, I wish I&#39;d put it that way&quot;</li><li>List any points of agreement, especially if they are not matters of general consensus</li><li>Mention anything you have learned from them</li><li>Only then offer your critique or rebuttal</li></ol><hr><h2 id="encouraged-behaviors" tabindex="-1">Encouraged Behaviors <a class="header-anchor" href="#encouraged-behaviors" aria-label="Permalink to &quot;Encouraged Behaviors&quot;">​</a></h2><ul><li><strong>Assume good faith</strong> until proven otherwise</li><li><strong>Ask clarifying questions</strong> before forming conclusions</li><li><strong>Cite primary sources</strong> when making claims</li><li><strong>Acknowledge when you&#39;re wrong</strong> or have learned something new</li><li><strong>Separate the argument from the person</strong> making it</li><li><strong>Be willing to change your mind</strong> when presented with better evidence</li><li><strong>Take breaks</strong> if discussions become heated</li></ul><h2 id="discouraged-behaviors" tabindex="-1">Discouraged Behaviors <a class="header-anchor" href="#discouraged-behaviors" aria-label="Permalink to &quot;Discouraged Behaviors&quot;">​</a></h2><ul><li>Sharing screenshots outside the community without permission</li><li>Personal attacks or doxxing</li><li>Deliberately misrepresenting others&#39; positions</li><li>Arguing in bad faith to &quot;win&quot; rather than understand</li><li>Spreading unverified information as fact</li><li>Brigading or coordinated harassment</li></ul><hr><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/community/">Community Guidelines</a></li><li><a href="/community/join.html">Join the Community</a></li><li><a href="/general/structured-analytic-techniques-sats.html">Structured Analytic Techniques</a></li></ul>',46)])])}const m=t(r,[["render",n]]);export{g as __pageData,m as default};
